    def _compute_anomaly_score(
        self,
        vibration: List[float],
        thermal: List[float],
        rpm: List[float],
        current: List[float]
    ) -> float:
        """Compute fused anomaly score using statistical z-score aggregation."""
        scores = []

        if vibration:
            mean_v = np.mean(vibration)
            std_v = np.std(vibration) + 1e-8
            scores.append(abs(vibration[-1] - mean_v) / std_v)

        if thermal:
            mean_t = np.mean(thermal)
            std_t = np.std(thermal) + 1e-8
            scores.append(abs(thermal[-1] - mean_t) / std_t)

        if rpm:
            mean_r = np.mean(rpm)
            std_r = np.std(rpm) + 1e-8
            scores.append(abs(rpm[-1] - mean_r) / std_r)

        if current:
            mean_c = np.mean(current)
            std_c = np.std(current) + 1e-8
            scores.append(abs(current[-1] - mean_c) / std_c)

        if not scores:
            return 0.0

        # Weighted fusion (equal weights for simplicity)
        return float(np.mean(scores))

    async def _compute_ttf_async(self, vibration_data: List[float]) -> Optional[float]:
        """
        Compute Time-To-Failure using exponential degradation model.
        Offloaded to thread pool to avoid blocking async loop.
        """
        def _compute():
            if len(vibration_data) < TTF_FORECAST_WINDOW:
                return None

            # Use last N samples for trend analysis
            recent = np.array(vibration_data[-TTF_FORECAST_WINDOW:])
            x = np.arange(len(recent))

            # Linear regression on log-transformed vibration (exponential growth model)
            try:
                log_y = np.log(recent + 1e-8)
                coeffs = np.polyfit(x, log_y, 1)
                growth_rate = coeffs[0]

                if growth_rate <= 0:
                    return None  # No degradation trend

                # Threshold for failure (5x baseline)
                baseline = np.median(recent[:50])
                failure_threshold = baseline * 5.0
                current_level = recent[-1]

                if current_level <= 0:
                    return None

                # TTF = ln(failure_threshold / current_level) / growth_rate
                ttf = np.log(failure_threshold / current_level) / growth_rate
                return max(0.0, float(ttf))
            except (np.linalg.LinAlgError, ValueError):
                return None

        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self._executor, _compute)

